// ═══ KOS KNOWLEDGE AUTO-EXPANSION ANALYZER ═══
const pendingReview = $input.all()[0]?.json || [];
const pendingEmbedding = $input.all()[1]?.json || [];
const latestKpi = $input.all()[2]?.json || [];

const now = new Date().toISOString();

const analysis = {
  timestamp: now,
  pending_review_count: pendingReview.length,
  pending_embedding_count: pendingEmbedding.length,
  latest_kpi: latestKpi[0] || null,
  action_required: pendingReview.length > 0 || pendingEmbedding.length > 0,
  batch_plan: []
};

// Plan auto-review for pending documents
if (pendingReview.length > 0) {
  // Auto-approve documents from trusted sources
  const trustedSources = ['BCEAO', 'COBAC', 'OHADA', 'GAFI', 'BANK_OF_GHANA'];
  const autoApprove = pendingReview.filter(d => 
    trustedSources.some(s => (d.source || '').toUpperCase().includes(s))
  );

  if (autoApprove.length > 0) {
    analysis.batch_plan.push({
      action: 'auto_approve',
      count: autoApprove.length,
      doc_ids: autoApprove.map(d => d.id),
      priority: 'high',
      reason: 'trusted_regulatory_source'
    });
  }

  // Queue remaining for human review
  const needReview = pendingReview.filter(d => 
    !trustedSources.some(s => (d.source || '').toUpperCase().includes(s))
  );

  if (needReview.length > 0) {
    analysis.batch_plan.push({
      action: 'queue_review',
      count: needReview.length,
      doc_ids: needReview.map(d => d.id),
      priority: 'medium',
      reason: 'requires_human_review'
    });
  }
}

// Plan embedding for approved documents
if (pendingEmbedding.length > 0) {
  // Determine target Qdrant collection based on source
  const batches = {};
  for (const doc of pendingEmbedding) {
    const source = (doc.source || 'general').toUpperCase();
    let collection = 'kos_business_knowledge';

    if (source.includes('BCEAO') || source.includes('COBAC') || source.includes('OHADA') || source.includes('GAFI')) {
      collection = 'kos_regulatory_knowledge';
    } else if (source.includes('AUDIT') || source.includes('KHEPRA')) {
      collection = 'kos_audit_intelligence';
    }

    if (!batches[collection]) batches[collection] = [];
    batches[collection].push(doc.id);
  }

  for (const [collection, docIds] of Object.entries(batches)) {
    analysis.batch_plan.push({
      action: 'embed_to_qdrant',
      collection: collection,
      count: docIds.length,
      doc_ids: docIds,
      priority: 'high'
    });
  }
}

return analysis;

// ═══ AUTO-APPROVE TRUSTED DOCUMENTS ═══
const analysis = $input.all()[0]?.json;
const autoApprove = (analysis.batch_plan || []).filter(p => p.action === 'auto_approve');

if (autoApprove.length === 0) {
  return { executed: false };
}

return {
  executed: true,
  total_docs: autoApprove.reduce((sum, p) => sum + p.count, 0),
  batches: autoApprove
};

// ═══ BUILD PATCH URL ═══
const batches = $input.all()[0]?.json?.batches || [];
if (batches.length === 0) return { url: null };
const ids = batches[0].doc_ids.join(',');
const baseUrl = ($env.SUPABASE_URL || '').replace(/\/$/, '');
return { url: baseUrl + '/rest/v1/rag_documents?id=in.(' + ids + ')', ids: ids };

// ═══ TRIGGER EMBEDDING PIPELINE ═══
const analysis = $input.all()[0]?.json;
const embedBatches = (analysis.batch_plan || []).filter(p => p.action === 'embed_to_qdrant');

if (embedBatches.length === 0) {
  return { executed: false };
}

return {
  executed: true,
  batches: embedBatches.map(b => ({
    collection: b.collection,
    doc_ids: b.doc_ids,
    count: b.count
  }))
};

return {
  timestamp: new Date().toISOString(),
  status: 'no_action',
  message: 'Knowledge pipeline up to date — no new documents to process.'
};
